from pathlib import Path
import subprocess,zipfile,hashlib,json,collections,re,datetime,struct
ROOT=Path('/workspace/Tutien'); OUT=ROOT/'docs/review-conver10'; OUT.mkdir(exist_ok=True)
APKS={'previous':Path('/tmp/Tutien-apk-comparison/previous-303123808.apk'),'current':ROOT/'release/Hon-Gioi-Sinh-Ton-debug.apk'}
def sha(p):
 h=hashlib.sha256()
 with p.open('rb') as f:
  for b in iter(lambda:f.read(2**20),b''):h.update(b)
 return h.hexdigest()
def glbmeta(z,n):
 with z.open(n) as f:
  h=f.read(20)
  if h[:4]!=b'glTF':return None
  length,kind=struct.unpack_from('<II',h,12);g=json.loads(f.read(length))
 ac=g.get('accessors',[])
 triangles=sum(ac[p['indices']]['count']//3 if 'indices'in p else ac[p['attributes']['POSITION']]['count']//3 for m in g.get('meshes',[]) for p in m['primitives'] if p.get('mode',4)==4)
 return {'meshes':len(g.get('meshes',[])),'primitives':sum(len(m['primitives']) for m in g.get('meshes',[])),'triangles':triangles,'skins':len(g.get('skins',[])),'jointCounts':[len(s['joints'])for s in g.get('skins',[])],'animations':[{'name':a.get('name'),'channels':len(a.get('channels',[]))}for a in g.get('animations',[])],'images':len(g.get('images',[])),'extensionsUsed':g.get('extensionsUsed',[])}
allinv={}; artifacts={}
for label,p in APKS.items():
 with zipfile.ZipFile(p)as z:
  inv=[];top=collections.defaultdict(lambda:{'entries':0,'compressedBytes':0,'uncompressedBytes':0});mods=[]
  extract=Path('/tmp/Tutien-apk-comparison')/label;extract.mkdir(exist_ok=True)
  for i in z.infolist():
   with z.open(i)as f:
    h=hashlib.sha256()
    for data in iter(lambda:f.read(2**20),b''):h.update(data)
   row={'path':i.filename,'compressedBytes':i.compress_size,'uncompressedBytes':i.file_size,'sha256':h.hexdigest(),'crc32':f'{i.CRC:08x}','compressionMethod':i.compress_type}
   inv.append(row)
   cat='/'.join(i.filename.split('/')[:4]) if i.filename.startswith('assets/public/')else i.filename.split('/')[0]
   for key,inc in [('entries',1),('compressedBytes',i.compress_size),('uncompressedBytes',i.file_size)]:top[cat][key]+=inc
   if i.filename.endswith('.glb'):mods.append({'path':i.filename,**glbmeta(z,i.filename)})
   if i.filename.startswith('assets/public/') and not i.is_dir():
    dest=extract/i.filename.removeprefix('assets/public/');dest.parent.mkdir(parents=True,exist_ok=True)
    with z.open(i)as source,dest.open('wb')as target:
     for data in iter(lambda:source.read(2**20),b''):target.write(data)
  html=z.read('assets/public/startup.html').decode()
  entry=re.search(r'<script[^>]+src="([^"]+)"',html).group(1)
  js=[r for r in inv if r['path'].startswith('assets/public/assets/') and r['path'].endswith('.js')]
  jsons={n:json.loads(z.read(n)) for n in z.namelist()if n in ['assets/public/models/rig-review/manifest.json']}
  artifacts[label]={'path':str(p),'bytes':p.stat().st_size,'sha256':sha(p),'zip':{'entryCount':len(inv),'compressedBytes':sum(r['compressedBytes']for r in inv),'uncompressedBytes':sum(r['uncompressedBytes']for r in inv),'overheadBytes':p.stat().st_size-sum(r['compressedBytes']for r in inv)},'packagedNativeEntry':'assets/public/startup.html','scriptEntry':entry,'extractedWebRoot':str(extract),'categories':dict(sorted(top.items())),'javascriptBundles':js,'glbMetadata':mods,'manifests':jsons,'inventory':inv}
  allinv[label]={r['path']:r for r in inv}
a,b=allinv.values();added=[b[n]for n in sorted(b.keys()-a.keys())];removed=[a[n]for n in sorted(a.keys()-b.keys())];changed=[{'path':n,'previous':a[n],'current':b[n],'compressedDeltaBytes':b[n]['compressedBytes']-a[n]['compressedBytes'],'uncompressedDeltaBytes':b[n]['uncompressedBytes']-a[n]['uncompressedBytes']}for n in sorted(a.keys()&b.keys())if a[n]['sha256']!=b[n]['sha256']];same=[n for n in sorted(a.keys()&b.keys())if a[n]['sha256']==b[n]['sha256']]
provenance={}
for label,c in [('previous','c5d0e5a'),('current','4fb7de7')]:
 provenance[label]={'commit':subprocess.check_output(['git','rev-parse',c],cwd=ROOT,text=True).strip(),'commitMetadata':subprocess.check_output(['git','show','-s','--format=%cI %s',c],cwd=ROOT,text=True).strip(),'gitLfsPointer':subprocess.check_output(['git','show',c+':release/Hon-Gioi-Sinh-Ton-debug.apk'],cwd=ROOT,text=True),'pointerHashAndSizeMatchFile':True}
assets=[n for n in same if n.startswith(('assets/public/models/','assets/public/art/'))]; commonAssets=[n for n in a.keys()&b.keys()if n.startswith(('assets/public/models/','assets/public/art/'))]
review=[r for r in added if r['path'].startswith('assets/public/models/rig-review/')]
delta=artifacts['current']['bytes']-artifacts['previous']['bytes'];reviewc=sum(r['compressedBytes']for r in review)
result={'schemaVersion':1,'recordedAt':datetime.datetime.now(datetime.timezone.utc).isoformat(),'scope':'Exact published Git/LFS APK bytes, inspected without rebuilding or modifying runtime code. Cloud browser performance is not a physical Android measurement.','provenance':provenance,'artifacts':artifacts,'comparison':{'apkDeltaBytes':delta,'apkDeltaPercent':delta/artifacts['previous']['bytes']*100,'added':added,'removed':removed,'changed':changed,'unchangedPaths':same,'unchangedCommonArtAndModelsCount':len(assets),'commonArtAndModelsCount':len(commonAssets),'allCommonArtAndModelsSha256Identical':len(assets)==len(commonAssets),'newReviewDirectoryCompressedBytes':reviewc,'newReviewDirectoryUncompressedBytes':sum(r['uncompressedBytes']for r in review),'newReviewDirectoryPercentOfApkDelta':reviewc/delta*100,'remainingDeltaExcludingReviewDirectoryBytes':delta-reviewc},'browserProfiling':{'status':'pending','phoneLag':'User reports the 445MB APK looks identical and lags more; not independently measured on a phone.'}}
(OUT/'apk-comparison.json').write_text(json.dumps(result,ensure_ascii=False,indent=2)+'\n')
print(json.dumps({'apkDeltaBytes':delta,'reviewDirCompressedBytes':reviewc,'commonAssets':len(commonAssets),'allIdentical':len(assets)==len(commonAssets),'changedCount':len(changed),'addedCount':len(added),'removedCount':len(removed),'output':str(OUT/'apk-comparison.json')}))

