import { createServer } from 'node:http';
import { readFile, stat, writeFile } from 'node:fs/promises';
import { resolve, extname } from 'node:path';
import { chromium } from '/workspace/Tutien/node_modules/playwright-core/index.mjs';
const base='/tmp/Tutien-apk-comparison';
const out='/workspace/Tutien/docs/review-conver10';
const types={'.html':'text/html','.js':'text/javascript','.css':'text/css','.json':'application/json','.glb':'model/gltf-binary','.wasm':'application/wasm','.svg':'image/svg+xml','.png':'image/png','.webp':'image/webp','.ktx2':'image/ktx2'};
const servers=[];
for(const [label,port]of[['previous',5196],['current',5197]]){
 const root=resolve(base,label);
 const server=createServer(async(req,res)=>{try{let path=decodeURIComponent(new URL(req.url,'http://localhost').pathname);if(path==='/')path='/startup.html';const file=resolve(root,'.'+path);if(!file.startsWith(root+'/')){res.writeHead(403).end();return;}const s=await stat(file);if(!s.isFile()){res.writeHead(404).end();return;}res.writeHead(200,{'Content-Type':types[extname(file)]??'application/octet-stream','Content-Length':s.size,'Cache-Control':'no-store'});res.end(await readFile(file));}catch{res.writeHead(404).end();}});
 await new Promise(resolve=>server.listen(port,'127.0.0.1',resolve));servers.push(server);
}
const flags=['--no-sandbox','--use-gl=angle','--use-angle=swiftshader','--enable-unsafe-swiftshader'];
const report={startedAt:new Date().toISOString(),status:'running',method:{runOrder:['previous','current','current','previous'],browser:'Chromium /usr/bin/chromium; ANGLE SwiftShader software rendering',flags,viewport:{width:960,height:432},deviceScaleFactor:1,hasTouch:true,quality:'balanced',entry:'startup.html?perf=1',contexts:'Fresh browser, page, storage and caches per run; one browser at a time',nativeSimulation:'Only Capacitor.isNativePlatform() returns true to follow packaged native boot service-worker bypass. No real Android bridge/WebView/device is present.',sampling:'8 seconds per lobby stage; per-stage main rAF deltas, long tasks, worker FPS/render counters before/after; exact diagnostic objects retained',limitations:['Cloud CPU/software GPU only; cannot infer phone FPS, thermal behavior or actual APK install/Android WebView memory.','Main-thread requestAnimationFrame intervals do not count worker-rendered frames. Worker fps and render counters are separate.','Timing variation and first-load shader/source parsing can dominate; tiny sample cannot establish causation for phone lag.','Screenshot poses are explicitly sought to fixed entrance time after measurement; they do not establish real-time animation quality.']},runs:[]};
async function save(){await writeFile(base+'/browser-report.json',JSON.stringify(report,null,2)+'\n');}
async function diagnostic(page){return await page.evaluate(async()=>{const g=window.__HON_GIOI__,w=g?.world;return{build:g?.build,boot:g?.boot,lifecycle:g?.lifecycle,backend:w?.backend,diagnostic:w?.inspect?await w.inspect():null};});}
async function sample(page,name,ms=8000){
 const before=await diagnostic(page);
 const frame=await page.evaluate(async(ms)=>{
  const samples=[];const start=performance.now();const longTasks=[];let observer;
  try{observer=new PerformanceObserver(list=>longTasks.push(...list.getEntries().map(e=>({startTime:e.startTime,duration:e.duration}))));observer.observe({entryTypes:['longtask']});}catch{}
  let last=performance.now();await new Promise(resolve=>{function next(now){samples.push(now-last);last=now;if(now-start>=ms)resolve();else requestAnimationFrame(next);}requestAnimationFrame(next);});observer?.disconnect();
  const sorted=[...samples].sort((a,b)=>a-b);const p=q=>sorted[Math.min(sorted.length-1,Math.floor((sorted.length-1)*q))];
  return{durationMs:performance.now()-start,frameIntervalsMs:samples,mainRaf:{count:samples.length,medianMs:p(.5),p95Ms:p(.95),maxMs:Math.max(...samples),over50:samples.filter(n=>n>50).length},longTasks};
 },ms);
 return{name,before,after:await diagnostic(page),...frame};
}
try{
 for(const [index,label]of report.method.runOrder.entries()){
  const run={index,label,startedAt:new Date().toISOString(),errors:[],consoleErrors:[],requestFailures:[],requests:[],stages:[],screenshots:[]};report.runs.push(run);await save();
  const browser=await chromium.launch({executablePath:'/usr/bin/chromium',headless:true,args:flags});
  try{
   run.browserVersion=browser.version();
   const context=await browser.newContext({viewport:report.method.viewport,deviceScaleFactor:1,hasTouch:true,serviceWorkers:'block'});const page=await context.newPage();
   page.on('pageerror',e=>run.errors.push(e.message));page.on('console',m=>{if(m.type()==='error')run.consoleErrors.push(m.text());});page.on('request',req=>run.requests.push(req.url()));page.on('requestfailed',req=>run.requestFailures.push({url:req.url(),error:req.failure()?.errorText}));
   await page.addInitScript(()=>{localStorage.setItem('hon-gioi-quality','balanced');window.Capacitor={isNativePlatform:()=>true};});
   const port=label==='previous'?5196:5197;const started=performance.now();
   await page.goto(`http://127.0.0.1:${port}/startup.html?perf=1`,{waitUntil:'domcontentloaded',timeout:120000});
   await page.waitForFunction(()=>window.__HON_GIOI__?.world?.previewAsset?.sourceFidelity?.status==='loaded',null,{timeout:180000});
   run.h01OriginalReadyMs=performance.now()-started;console.log(JSON.stringify({index,label,h01ReadyMs:run.h01OriginalReadyMs}));
   run.stages.push(await sample(page,'H01-lobby-idle'));
   await page.evaluate(()=>window.__HON_GIOI__.world.replayHeroEntrance());
   run.stages.push(await sample(page,'H01-entrance-replay'));
   if(index<2){
    for(const time of[2.1,6]){await page.evaluate(time=>window.__HON_GIOI__.world.seekHeroEntrance(time),time);await page.waitForTimeout(500);const path=`${out}/apk-${label}-h01-t${String(time).replace('.','_')}.png`;await page.screenshot({path});run.screenshots.push({path,capturedAt:new Date().toISOString(),entranceSeconds:time});}
   }
   const changed=performance.now();await page.locator('[data-hero="1"]').tap({timeout:60000});
   await page.waitForFunction(()=>window.__HON_GIOI__?.world?.previewAsset?.id==='H02-C0'&&window.__HON_GIOI__.world.previewAsset.sourceFidelity?.status==='loaded',null,{timeout:180000});run.h02OriginalReadyAfterHeroTapMs=performance.now()-changed;console.log(JSON.stringify({index,label,h02ReadyMs:run.h02OriginalReadyAfterHeroTapMs}));
   run.stages.push(await sample(page,'H02-lobby-idle'));
   await page.evaluate(()=>window.__HON_GIOI__.world.replayHeroEntrance());run.stages.push(await sample(page,'H02-entrance-replay'));
   if(index<2){for(const time of[2.1,6]){await page.evaluate(time=>window.__HON_GIOI__.world.seekHeroEntrance(time),time);await page.waitForTimeout(500);const path=`${out}/apk-${label}-h02-t${String(time).replace('.','_')}.png`;await page.screenshot({path});run.screenshots.push({path,capturedAt:new Date().toISOString(),entranceSeconds:time});}}
   await page.locator('#start').tap({timeout:60000});await page.waitForFunction(()=>window.__HON_GIOI__?.match?.time>0,null,{timeout:180000});run.stages.push(await sample(page,'H02-match-idle'));
   if(index<2){const path=`${out}/apk-${label}-h02-match.png`;await page.screenshot({path});run.screenshots.push({path,capturedAt:new Date().toISOString()});}
   run.resources=await page.evaluate(()=>performance.getEntriesByType('resource').map(r=>({name:r.name,initiatorType:r.initiatorType,startTime:r.startTime,duration:r.duration,transferSize:r.transferSize,encodedBodySize:r.encodedBodySize,decodedBodySize:r.decodedBodySize})));
   run.status='complete';
  }catch(e){run.status='failed';run.failure=e.stack??String(e);console.log(JSON.stringify({index,label,failure:run.failure}));}
  finally{await browser.close();run.finishedAt=new Date().toISOString();await save();}
 }
 report.status=report.runs.every(r=>r.status==='complete')?'complete':'partial';report.finishedAt=new Date().toISOString();await save();
}finally{for(const server of servers)await new Promise(resolve=>server.close(resolve));}
console.log(JSON.stringify({status:report.status,output:base+'/browser-report.json'}));
